begin;
create function app_private.guard_procurement_record() returns trigger language plpgsql set search_path='' as $$begin
 if tg_op='DELETE' then raise exception 'procurement history retained' using errcode='55000';end if;
 if tg_table_name='supplier_eligibility_versions' then
 if old.status<>'draft' and not(old.status='approved' and new.status='retired' and(to_jsonb(new)-array['status','updated_at'])=(to_jsonb(old)-array['status','updated_at'])) then raise exception 'approved supplier verification immutable' using errcode='55000';end if;
 elsif tg_table_name='procurement_rfqs' then
 if old.status in ('closed','cancelled') or(to_jsonb(new)-array['status','customer_approved_by','customer_approved_at','updated_at'])<>(to_jsonb(old)-array['status','customer_approved_by','customer_approved_at','updated_at']) or(old.customer_approved_by is not null and(new.customer_approved_by is distinct from old.customer_approved_by or new.customer_approved_at is distinct from old.customer_approved_at)) then raise exception 'RFQ terms and customer authorisation immutable' using errcode='55000';end if;
 elsif tg_table_name='supplier_quotation_versions' then
 if old.status<>'draft' and not(new.status in ('withdrawn','superseded') and old.status='submitted' and(to_jsonb(new)-array['status','updated_at'])=(to_jsonb(old)-array['status','updated_at'])) then raise exception 'submitted supplier commercial terms immutable' using errcode='55000';end if;
 elsif tg_table_name='procurement_selections' then
 if old.status<>'proposed' and not(old.status='approved' and new.status='superseded' and(to_jsonb(new)-array['status','updated_at'])=(to_jsonb(old)-array['status','updated_at'])) then raise exception 'decided supplier selection immutable' using errcode='55000';end if;
 elsif tg_table_name='purchase_order_versions' then
 if old.acknowledged_by is not null or(to_jsonb(new)-array['acknowledged_by','acknowledged_at','updated_at'])<>(to_jsonb(old)-array['acknowledged_by','acknowledged_at','updated_at']) then raise exception 'issued purchase terms immutable' using errcode='55000';end if;
 elsif tg_table_name='procurement_receipts' then
 if old.status in ('accepted','rejected') or(to_jsonb(new)-array['status','inspected_by','inspected_at','updated_at'])<>(to_jsonb(old)-array['status','inspected_by','inspected_at','updated_at']) then raise exception 'receipt provenance and final inspection immutable' using errcode='55000';end if;
 elsif tg_table_name='procurement_receipt_lines' then
 if old.accepted_quantity is not null or(to_jsonb(new)-array['accepted_quantity','rejected_quantity','condition_snapshot','case_id','updated_at'])<>(to_jsonb(old)-array['accepted_quantity','rejected_quantity','condition_snapshot','case_id','updated_at']) then raise exception 'declared quantity and final goods inspection immutable' using errcode='55000';end if;
 elsif tg_table_name='procurement_returns' then
 if old.status in ('replaced','resolved') or(to_jsonb(new)-array['status','supplier_received_by','replacement_receipt_line_id','updated_at'])<>(to_jsonb(old)-array['status','supplier_received_by','replacement_receipt_line_id','updated_at']) then raise exception 'return quantity and final reconciliation immutable' using errcode='55000';end if;
 elsif tg_table_name in ('procurement_rfq_items','procurement_rfq_recipients') then
 raise exception 'RFQ items and invitations immutable; prepare a new version' using errcode='55000';
 end if;return new;end$$;
do $$declare name text;begin foreach name in array array['supplier_eligibility_versions','procurement_rfqs','procurement_rfq_items','procurement_rfq_recipients','supplier_quotation_versions','procurement_selections','purchase_order_versions','procurement_receipts','procurement_receipt_lines','procurement_returns'] loop execute format('create trigger procurement_guard before update or delete on private.%I for each row execute function app_private.guard_procurement_record()',name);end loop;end$$;
alter function app_private.read_service_operation(uuid,uuid,integer) rename to read_operation_before_procurement;
revoke all on function app_private.read_operation_before_procurement(uuid,uuid,integer) from public,anon,authenticated;
create function app_private.read_service_operation(p_operation uuid,p_after uuid default null,p_limit integer default 25) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare operation private.service_operations;result jsonb;staff boolean;begin
 result=app_private.read_operation_before_procurement(p_operation,p_after,p_limit);
 select * into operation from private.service_operations where id=p_operation;
 if operation.kind<>'procurement' then return result;end if;
 staff=app_private.operation_staff(operation.id,'procurement.source') or app_private.operation_staff(operation.id,'specialized.read');
 result=result||jsonb_build_object('rfqs',(select coalesce(jsonb_agg(jsonb_build_object('id',page.id,'reference',page.reference,'version',page.version,'status',page.status,'closes_at',page.closes_at,'required_at',page.required_at,'terms',page.terms,'customer_approved_at',page.customer_approved_at,
 'invitation_id',(select id from private.procurement_rfq_recipients where rfq_id=page.id and app_private.supplier_actor(supplier_organisation_id) limit 1),
 'items',(select coalesce(jsonb_agg(jsonb_build_object('id',item.id,'code',item.code,'description',item.description,'specification',item.specification,'quantity',item.quantity::text,'unit',item.unit)),'[]') from private.procurement_rfq_items item where item.rfq_id=page.id))),'[]') from(select rfq.* from private.procurement_rfqs rfq where rfq.operation_id=operation.id and(p_after is null or rfq.id>p_after) and(staff or app_private.operation_customer(operation.id) or(rfq.status<>'draft' and exists(select 1 from private.procurement_rfq_recipients where rfq_id=rfq.id and app_private.supplier_actor(supplier_organisation_id)))) order by rfq.id limit p_limit) page));
 result=result||jsonb_build_object('quotes',(select coalesce(jsonb_agg(jsonb_build_object('id',quote.id,'rfq_id',quote.rfq_id,'supplier_id',quote.supplier_organisation_id,'version',quote.version,'status',quote.status,'currency_id',quote.currency_id,'minor_units',quote.minor_units,'total',quote.total::text,'valid_until',quote.valid_until,'conditions',quote.conditions,
 'lines',(select coalesce(jsonb_agg(jsonb_build_object('id',line.id,'item_id',line.rfq_item_id,'quantity',line.quantity::text,'unit_price',line.unit_price::text,'discount',line.discount::text,'tax',line.tax_snapshot,'total',line.line_total::text)),'[]') from private.supplier_quotation_lines line where line.quotation_version_id=quote.id))),'[]') from(select q.* from private.supplier_quotation_versions q join private.procurement_rfqs rfq on rfq.id=q.rfq_id where rfq.operation_id=operation.id and(staff or app_private.supplier_actor(q.supplier_organisation_id)) and(p_after is null or q.id>p_after) order by q.id limit p_limit) quote));
 result=result||jsonb_build_object('purchase_orders',(select coalesce(jsonb_agg(jsonb_build_object('id',po.id,'reference',po.reference,'status',po.status,'revision',po.revision,'supplier_id',po.supplier_organisation_id,
 'versions',(select coalesce(jsonb_agg(jsonb_build_object('id',version.id,'version',version.version,'currency_id',version.currency_id,'minor_units',version.minor_units,'total',version.total::text,'terms',version.terms_snapshot-'commercial_version_id','acknowledged_at',version.acknowledged_at,
 'lines',(select coalesce(jsonb_agg(jsonb_build_object('id',line.id,'quantity',line.quantity::text,'unit',line.unit,'total',line.line_total::text,'specification',line.specification_snapshot,'received',app_private.procurement_net_received(line.id)::text)),'[]') from private.purchase_order_lines line where line.version_id=version.id)) order by version.version desc),'[]') from private.purchase_order_versions version where version.purchase_order_id=po.id))),'[]') from(select parent.* from private.purchase_orders parent where parent.operation_id=operation.id and(staff or app_private.supplier_actor(parent.supplier_organisation_id)) and(p_after is null or parent.id>p_after) order by parent.id limit p_limit) po));
 result=result||jsonb_build_object('receipts',(select coalesce(jsonb_agg(jsonb_build_object('id',receipt.id,'version_id',receipt.version_id,'status',receipt.status,'task_id',receipt.receiving_task_id,'inspected_at',receipt.inspected_at,
 'lines',(select coalesce(jsonb_agg(jsonb_build_object('id',line.id,'line_id',line.purchase_order_line_id,'sent',line.sent_quantity::text,'accepted',line.accepted_quantity::text,'rejected',line.rejected_quantity::text,'condition',line.condition_snapshot)),'[]') from private.procurement_receipt_lines line where line.receipt_id=receipt.id))),'[]') from(select header.* from private.procurement_receipts header join private.purchase_order_versions version on version.id=header.version_id join private.purchase_orders po on po.id=version.purchase_order_id where header.operation_id=operation.id and(staff or app_private.supplier_actor(po.supplier_organisation_id) or app_private.execution_worker(header.receiving_task_id)) and(p_after is null or header.id>p_after) order by header.id limit p_limit) receipt));
 if staff then result=result||jsonb_build_object('selections',(select coalesce(jsonb_agg(to_jsonb(choice)),'[]') from(select * from private.procurement_selections where operation_id=operation.id order by id limit p_limit) choice),'supplier_eligibility',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'supplier_id',organisation_id,'status',status,'valid_until',valid_until)),'[]') from private.supplier_eligibility_versions where service_version_id=operation.service_version_id),'returns',(select coalesce(jsonb_agg(to_jsonb(return_row)||jsonb_build_object('quantity',return_row.quantity::text)),'[]') from private.procurement_returns return_row join private.procurement_receipt_lines line on line.id=return_row.receipt_line_id where line.operation_id=operation.id));end if;return result;
end$$;
grant execute on function app_private.read_service_operation(uuid,uuid,integer) to authenticated;
create or replace function public.read_service_operation(p_operation uuid,p_after uuid default null,p_limit integer default 25) returns jsonb language sql stable set search_path='' as $$select app_private.read_service_operation(p_operation,p_after,p_limit)$$;
commit;
